func (this *Coinbaseexchange) ParseTransactionStatus(transaction any) any {
	var canceled any = this.SafeValue(transaction, "canceled_at")
	if IsTrue(IsTrue((!IsEqual(canceled, nil))) && IsTrue((!IsEqual(canceled, nil)))) {
		return "canceled"
	}
	var processed any = this.SafeValue(transaction, "processed_at")
	var completed any = this.SafeValue(transaction, "completed_at")
	if IsTrue(IsTrue((!IsEqual(completed, nil))) && IsTrue((!IsEqual(completed, nil)))) {
		return "ok"
	} else if IsTrue(IsTrue((!IsEqual(processed, nil))) && IsTrue((!IsEqual(processed, nil)))) {
		return "failed"
	} else {
		return "pending"
	}
}
func (this *Coinbaseexchange) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// privateGetTransfers
	//
	//    [
	//        {
	//            "id": "bee6fd7c-afb2-4e47-8298-671d09997d16",
	//            "type": "deposit",
	//            "created_at": "2022-12-21 00:48:45.477503+00",
	//            "completed_at": null,
	//            "account_id": "sal3802-36bd-46be-a7b8-alsjf383sldak",     // only from privateGetTransfers
	//            "user_id": "6382048209f92as392039dlks2",                  // only from privateGetTransfers
	//            "amount": "0.01000000",
	//            "details": {
	//                "network": "litecoin",
	//                "crypto_address": "MKemtnCFUYKsNWaf5EMYMpwSszcXWFDtTY",
	//                "coinbase_account_id": "fl2b6925-f6ba-403n-jj03-40fl435n430f",
	//                "coinbase_transaction_id": "63a25bb13cb5cf0001d2cf17", // withdrawals only
	//                "crypto_transaction_hash": "752f35570736341e2a253f7041a34cf1e196fc56128c900fd03d99da899d94c1",
	//                "tx_service_transaction_id": "1873249104",
	//                "coinbase_payment_method_id": ""
	//            },
	//            "canceled_at": null,
	//            "processed_at": null,
	//            "user_nonce": null,
	//            "idem": "5e3201b0-e390-5k3k-a913-c32932049242",
	//            "profile_id": "k3k302a8-c4dk-4f49-9d39-3203923wpk39",
	//            "currency": "LTC"
	//        }
	//    ]
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var details any = this.SafeValue(transaction, "details", map[string]any{})
	var timestamp any = this.Parse8601(this.SafeString(transaction, "created_at"))
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var amount any = this.SafeNumber(transaction, "amount")
	var typeVar any = this.SafeString(transaction, "type")
	var address any = this.SafeString(details, "crypto_address")
	address = this.SafeString(transaction, "crypto_address", address)
	var fee map[string]any = map[string]any{
		"currency": nil,
		"cost":     nil,
		"rate":     nil,
	}
	if IsTrue(IsEqual(typeVar, "withdraw")) {
		typeVar = "withdrawal"
		address = this.SafeString(details, "sent_to_address", address)
		var feeCost any = this.SafeNumber(details, "fee")
		if IsTrue(!IsEqual(feeCost, nil)) {
			if IsTrue(!IsEqual(amount, nil)) {
				amount = Subtract(amount, feeCost)
			}
			AddElementToObject(fee, "cost", feeCost)
			AddElementToObject(fee, "currency", code)
		}
	}
	var networkId any = this.SafeString(details, "network")
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(details, "crypto_transaction_hash"),
		"type":        typeVar,
		"currency":    code,
		"network":     this.NetworkIdToCode(networkId, code),
		"amount":      amount,
		"status":      this.ParseTransactionStatus(transaction),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressFrom": nil,
		"addressTo":   this.SafeString(details, "crypto_address"),
		"tag":         this.SafeString(details, "destination_tag"),
		"tagFrom":     nil,
		"tagTo":       nil,
		"updated":     this.Parse8601(this.SafeString(transaction, "processed_at")),
		"comment":     nil,
		"internal":    false,
		"fee":         fee,
	}
}

